#!/bin/sh
# Tinty hook: palette for hyprlock
hex() {
  eval "printf '%s%s%s' \"\$TINTY_SCHEME_PALETTE_BASE${1}_HEX_R\" \"\$TINTY_SCHEME_PALETTE_BASE${1}_HEX_G\" \"\$TINTY_SCHEME_PALETTE_BASE${1}_HEX_B\""
}
cat > "$HOME/.config/hypr/themes/hyprlock-colors.conf" <<CONF
# Auto-generated by tinty — do not edit
\$bg = rgb($(hex 00))
\$fg = rgb($(hex 05))
\$dim = rgb($(hex 04))
\$accent = rgb($(hex 0D))
\$red = rgb($(hex 08))
CONF
